-- Уточнение по реальному тесту пользователя: переиспользование n14 (обычная
-- финальная ветка table_wrong) в качестве сигнала на "to" привело к тому,
-- что ОДИН И ТОТ ЖЕ дословный текст показывался в чате дважды подряд
-- (сигнал раньше, финальная ветка позже, если ученик потратил все три
-- попытки на других слотах) — читается как баг, а не как подсказка.
-- Правило переиспользования (уже было в базе) смягчено: по умолчанию для
-- сигнала пишем СВОЮ короткую ноду с ДРУГОЙ формулировкой, переиспользование
-- существующей — только при выполнении двух условий сразу (см. текст).
--
-- Проверено на конфликт: апдейт целится только в старую формулировку
-- (WHERE ловит текст без нового маркера "ДРУГОЙ формулировкой" — идемпотентно).
update public.lesson_rules
set rule_text = 'Прежде чем писать НОВУЮ ноду-сигнал — проверь, нет ли в уроке уже готовой ноды с подходящим объяснением (например, финальная ветка после трёх попыток той же самой ошибки, table_wrong/phrase_wrong/word_wrong). signals[].ref может ссылаться на ЛЮБУЮ ноду урока, в том числе уже стоящую в основном потоке графа — не обязательно строить отдельного «спутника» под каждый слот. НО: на практике переиспользование почти всегда рискованно — если ученик всё же дойдёт до этой ноды и обычным путём (три попытки потрачены на ДРУГИХ слотах), тот же самый ДОСЛОВНЫЙ текст покажется в чате второй раз подряд (сигнал раньше, обычная ветка позже) — это читается как баг, не как подсказка, даже если по смыслу текст «верный». Поэтому по умолчанию пиши для сигнала СВОЮ короткую ноду с ДРУГОЙ формулировкой (более краткий намёк, не дословный пересказ финальной ветки) — а не ссылайся на готовую подробную ноду напрямую. Переиспользование существующей ноды оправдано, только если два условия выполнены сразу: 1) её текст читается как самостоятельное объяснение независимо от контекста, и 2) ты сознательно проверил, что дословного повтора с чем-то, что уже могло прозвучать раньше (в т.ч. с этой же нодой через другой сигнал), не будет.'
where rule_text like 'Прежде чем писать НОВУЮ ноду-сигнал%'
  and rule_text not like '%ДРУГОЙ формулировкой%';
